/** 内部错误：带机器可读错误码。 */
class TaskError extends Error {
  constructor(
    readonly code: ErrorCode,
    message: string,
    readonly hint?: string,
  ) {
    super(message);
    this.name = 'TaskError';
  }
}

function failure(code: ErrorCode, message: string, hint?: string): ApiError {
  const error: ApiError = { ok: false, code, message };
  if (hint !== undefined) error.hint = hint;
  return error;
}

/** pendingOpen 的有效期：超过就作废（避免重启后突然跳去某个旧会话）。 */
const PENDING_OPEN_TTL_MS = 5 * 60 * 1000;

